use super::{translate::Translator, protocol::{Event, TurnStatus}};
use super::super::stream::Mailbox;
use crate::chat::ChatStreamEvent;
use std::{collections::VecDeque, sync::Arc, time::Instant};
pub struct Route {
    pub req: String,
    pub session: String,
    pub active: Arc<parking_lot::Mutex<std::collections::HashMap<String, String>>>,
    pub acknowledged: bool,
    pub started: bool,
    pub reservation: (Arc<parking_lot::Mutex<std::collections::HashSet<String>>>, String),
    pub turn: Option<String>,
    pub translator: Translator,
    pub stream: Arc<Mailbox>,
    pub deadline: Instant,
    pub abort_deadline: Option<Instant>,
    pub pending: VecDeque<ChatStreamEvent>,
    pub terminal: Option<(Option<ChatStreamEvent>, ChatStreamEvent)>,
}
impl Route {
    pub fn accept(&mut self, turn: String, event: Event) -> anyhow::Result<()> {
        if self.terminal.is_some() || self.stream.is_finished() { return Ok(()); }
        if !self.started {
            anyhow::ensure!(matches!(event, Event::Started), "AgentdTurnOrder: expected turn.started");
            self.started = true;
            if self.turn.is_none() { self.turn = Some(turn.clone()); }
        }
        anyhow::ensure!(self.turn.as_deref() == Some(&turn), "AgentdTurnMismatch");
        let events = self.translator.accept(event);
        self.enqueue(events);
        Ok(())
    }
    pub fn tick(&mut self) {
        if self.terminal.is_none() { let events = self.translator.tick(); self.enqueue(events); }
    }
    fn enqueue(&mut self, events: Vec<ChatStreamEvent>) {
        for event in events {
            if event.kind == "done" { self.terminal = Some((None, event)); }
            else { self.pending.push_back(event); }
        }
    }
    pub fn fail(&mut self, message: &str) {
        if self.stream.is_finished() { return; }
        self.acknowledged = true;
        if let Some((error, _)) = &mut self.terminal {
            *error = Some(self.translator.make("error", Some(message.into())));
            return;
        }
        let events = self.translator.flush();
        self.enqueue(events);
        self.terminal = Some((Some(self.translator.make("error", Some(message.into()))), self.translator.make("done", None)));
    }
    pub fn aborted(&mut self) {
        if self.terminal.is_none() {
            let events = self.translator.accept(Event::Completed { status: TurnStatus::Aborted });
            self.enqueue(events);
        }
    }
    pub fn drain(&mut self) -> bool {
        while let Some(event) = self.pending.pop_front() {
            if let Err(event) = self.stream.try_push(event) {
                self.pending.push_front(event);
                return false;
            }
        }
        if self.acknowledged {
            if let Some((error, done)) = self.terminal.take() {
                eprintln!("{}", serde_json::json!({"component":"agent.backend", "backend":"pi",
                    "reqId":self.req, "conversationId":done.conversation_id, "sessionId":self.session,
                    "phase":"done", "error":error.is_some()}));
                self.reservation.0.lock().remove(&self.reservation.1);
                self.active.lock().remove(&self.req);
                self.stream.finish(error, done);
            }
        }
        true
    }
}

impl Drop for Route {
    fn drop(&mut self) { self.reservation.0.lock().remove(&self.reservation.1); }
}
use super::{client::{Control, Reply}, process::Process, protocol::{Command, Empty, Frame, Id, Request, Session}, routes::Route};
use super::super::{config::Agentd, BackendStatus, BackendError};
use parking_lot::Mutex;
use std::{collections::HashMap, sync::Arc, time::{Duration, Instant}};
use tokio::sync::mpsc;
use serde_json::{Value, json};
struct Pending { reply: Option<Reply>, since: Instant }
struct State {
    config: Agentd,
    status: Arc<Mutex<BackendStatus>>,
    active: Arc<Mutex<HashMap<String, String>>>,
    routes: HashMap<String, Route>,
    pending: HashMap<Id, Pending>,
    counter: u64,
    failures: u32,
    next_start: Instant,
    last_ping: Instant,
    started: Instant,
    last_used: Instant,
    stopping: bool,
}
impl State {
    fn request(&mut self, process: &Process, command: Command, reply: Option<Reply>) -> anyhow::Result<()> {
        self.counter += 1;
        let id = Id::Text(format!("rust-{}", self.counter));
        process.write(&Request { id: id.clone(), command }, self.config.max_line_bytes)?;
        self.pending.insert(id, Pending { reply, since: Instant::now() });
        Ok(())
    }
    fn fail(&mut self, error: String) {
        self.failures = self.failures.saturating_add(1);
        let circuit = self.failures >= self.config.failure_threshold;
        let error = if circuit { format!("{}: {error}", BackendError::CircuitOpen) } else { error };
        for route in self.routes.values_mut() { route.fail(&error); }
        for (_, pending) in self.pending.drain() {
            if let Some(reply) = pending.reply { let _ = reply.send(Err(error.clone())); }
        }
        let mut status = self.status.lock();
        status.healthy = false;
        status.pid = None;
        status.circuit_open = circuit;
        status.last_error = Some(if circuit { BackendError::CircuitOpen.to_string() } else { error });
        let backoff = self.config.restart_base_ms.saturating_mul(1_u64 << self.failures.saturating_sub(1).min(30))
            .min(self.config.restart_max_ms);
        let mut bytes = [0_u8; 8];
        let _ = getrandom::getrandom(&mut bytes);
        let jitter = u64::from_le_bytes(bytes) % self.config.restart_jitter_ms.saturating_add(1).max(1);
        self.next_start = Instant::now() + Duration::from_millis(backoff.saturating_add(jitter).min(self.config.restart_max_ms));
    }
    fn frame(&mut self, frame: Frame) -> anyhow::Result<()> {
        match frame {
            Frame::Response { id, ok, result, error } => {
                let id = id.ok_or_else(|| anyhow::anyhow!("AgentdProtocolError: uncorrelated response"))?;
                if let Some(pending) = self.pending.remove(&id) {
                    let result = if ok { Ok(result.unwrap_or(Value::Null)) }
                        else { Err(error.map(|e| format!("{}: {}", e.code, e.message)).unwrap_or_else(|| "AgentdResponseError".into())) };
                    if let Some(reply) = pending.reply { let _ = reply.send(result); }
                    else {
                        let value = result.map_err(anyhow::Error::msg)?;
                        anyhow::ensure!(value.get("status").and_then(Value::as_str) == Some("ok"), "AgentdPingFailed");
                        self.status.lock().healthy = true;
                    }
                }
            }
            Frame::Event { session_id, turn_id, event } => {
                if let Some(route) = self.routes.get_mut(&session_id) { route.accept(turn_id, event)?; }
                // Events after a locally finalized abort are intentionally ignored.
            }
        }
        Ok(())
    }
    fn control(&mut self, command: Control, process: Option<&Process>) -> anyhow::Result<()> {
        self.last_used = Instant::now();
        match command {
            Control::Stop => { self.stopping = true; }
            Control::Fail(req, message) => {
                for route in self.routes.values_mut().filter(|r| r.req == req) { route.fail(&message); }
            }
            Control::Register { session, req, translator, stream, timeout, reservation, reply } => {
                if self.routes.contains_key(&session) {
                    let _ = reply.send(Err("AgentdSessionBusy".into()));
                } else if process.is_none() {
                    let _ = reply.send(Err(self.unavailable()));
                } else {
                    self.active.lock().insert(req.clone(), session.clone());
                    self.routes.insert(session.clone(), Route { req, session, active: self.active.clone(), acknowledged: false, started: false, reservation, turn: None, translator, stream,
                        deadline: Instant::now() + timeout, abort_deadline: None,
                        pending: Default::default(), terminal: None });
                    let _ = reply.send(Ok(json!({})));
                }
            }
            Control::Request(command, reply) => {
                if let Some(process) = process {
                    if let Err(e) = self.request(process, command, Some(reply.clone())) {
                        let _ = reply.send(Err(e.to_string()));
                        return Err(e);
                    }
                } else { let _ = reply.send(Err(self.unavailable())); }
            }
            Control::Bind(req, turn, reply) => {
                let route = self.routes.values_mut().find(|r| r.req == req);
                let result = match route {
                    Some(route) if route.turn.as_ref().is_none_or(|id| id == &turn) => {
                        route.turn = Some(turn);
                        route.acknowledged = true;
                        Ok(json!({}))
                    }
                    Some(route) => { route.fail("AgentdTurnMismatch"); Err("AgentdTurnMismatch".into()) }
                    None => Err("AgentdTurnMissing".into()),
                };
                let _ = reply.send(result);
            }
            Control::Cancel(req, reply) => {
                let session = self.active.lock().get(&req).cloned();
                if let Some(session) = session {
                    if let Some(route) = self.routes.get_mut(&session) {
                        route.abort_deadline = Some(Instant::now() + Duration::from_millis(self.config.abort_timeout_ms));
                    }
                    if let Some(process) = process {
                        // Abort response may arrive after turn.completed. Ignore only its result,
                        // using an ordinary reply prevents it being mistaken for a health ping.
                        let (tx, _rx) = std::sync::mpsc::sync_channel(1);
                        self.request(process, Command::Abort(Session { session_id: session }), Some(tx))?;
                    }
                }
                let _ = reply.send(Ok(json!({"accepted":true})));
            }
        }
        Ok(())
    }
    fn unavailable(&self) -> String {
        let status = self.status.lock();
        if status.circuit_open { BackendError::CircuitOpen.to_string() }
        else { status.last_error.clone().unwrap_or_else(|| "AgentdRestarting".into()) }
    }
    fn drain(&mut self) -> bool {
        let mut ready = true;
        self.routes.retain(|_, route| {
            route.tick();
            ready &= route.drain();
            if route.stream.is_finished() { self.active.lock().remove(&route.req); false } else { true }
        });
        ready
    }
    fn deadlines(&mut self) -> anyhow::Result<()> {
        for route in self.routes.values_mut() {
            if route.abort_deadline.is_some_and(|d| Instant::now() >= d) {
                route.aborted();
                anyhow::bail!("AgentdAbortTimeout: daemon restarted to stop the cancelled turn");
            }
            if Instant::now() >= route.deadline && route.terminal.is_none() {
                route.fail("AgentdTurnTimeout");
                anyhow::bail!("AgentdTurnTimeout");
            }
        }
        anyhow::ensure!(!self.pending.values().any(|p| p.since.elapsed().as_millis() >= self.config.request_timeout_ms as u128), "AgentdRequestTimeout");
        Ok(())
    }
}
pub async fn run(config: Agentd, mut rx: mpsc::Receiver<Control>, status: Arc<Mutex<BackendStatus>>,
    active: Arc<Mutex<HashMap<String, String>>>) {
    let now = Instant::now();
    let mut s = State { config, status, active, routes: HashMap::new(), pending: HashMap::new(),
        counter: 0, failures: 0, next_start: now, last_ping: now, started: now, last_used: now, stopping: false };
    let mut process: Option<Process> = None;
    let mut ever_started = false;
    let mut idle = false;
    let mut ticker = tokio::time::interval(Duration::from_millis(s.config.supervisor_tick_ms));
    loop {
        if !idle && process.is_none() && !s.status.lock().circuit_open && Instant::now() >= s.next_start {
            match Process::spawn(&s.config) {
                Ok(p) => {
                    { let mut status = s.status.lock(); status.pid = Some(p.pid); if ever_started { status.restarts += 1; } }
                    ever_started = true;
                    s.started = Instant::now();
                    s.last_ping = Instant::now();
                    if let Err(e) = s.request(&p, Command::Ping(Empty {}), None) { s.fail(e.to_string()); }
                    process = Some(p);
                }
                Err(e) => s.fail(e.to_string()),
            }
        }
        let ready = s.drain();
        let outcome: anyhow::Result<()> = tokio::select! {
            command = rx.recv() => {
                match command {
                    Some(command) => {
                        if idle {
                            idle = false;
                            match Process::spawn(&s.config) {
                                Ok(p) => {
                                    { let mut status = s.status.lock(); status.pid = Some(p.pid); status.restarts += 1; }
                                    s.started = Instant::now();
                                    s.last_ping = Instant::now();
                                    if let Err(error) = s.request(&p, Command::Ping(Empty {}), None) { s.fail(error.to_string()); }
                                    process = Some(p);
                                }
                                Err(e) => s.fail(e.to_string()),
                            }
                        }
                        s.control(command, process.as_ref())
                    }
                    None => { s.stopping = true; Ok(()) }
                }
            }
            frame = async { match &mut process { Some(p) => p.incoming.recv().await, None => std::future::pending().await } }, if ready => {
                match frame { Some(Ok(frame)) => s.frame(frame), Some(Err(e)) => Err(e), None => Err(anyhow::anyhow!("AgentdEof")) }
            }
            _ = ticker.tick() => {
                let deadlines = s.deadlines();
                if let Some(p) = &mut process {
                    if p.exited().unwrap_or(true) { Err(anyhow::anyhow!("AgentdExited")) }
                    else if deadlines.is_err() { deadlines }
                    else if ready && s.last_ping.elapsed().as_millis() >= s.config.ping_interval_ms as u128 {
                        s.last_ping = Instant::now();
                        s.request(p, Command::Ping(Empty {}), None)
                    } else {
                        if s.status.lock().healthy && s.started.elapsed().as_millis() >= s.config.stable_reset_ms as u128 { s.failures = 0; }
                        Ok(())
                    }
                } else { deadlines }
            }
        };
        if let Err(error) = outcome {
            if let Some(mut p) = process.take() { p.stop().await; }
            s.fail(error.to_string());
        }
        if s.stopping {
            for route in s.routes.values_mut() { route.fail("AgentdShutdown"); }
            if let Some(mut p) = process.take() { p.stop().await; }
            // Delivery is cancellable by dropping the receiver; keep draining retained events.
            while !s.routes.is_empty() { s.drain(); ticker.tick().await; }
            break;
        }
        if process.is_some() && s.routes.is_empty() && s.pending.is_empty()
            && s.last_used.elapsed().as_millis() >= s.config.idle_ms as u128 {
            if let Some(mut p) = process.take() { p.stop().await; }
            let mut status = s.status.lock(); status.pid = None; status.healthy = false;
            idle = true;
        }
    }
    let mut status = s.status.lock(); status.pid = None; status.healthy = false;
}

import { InMemoryCredentialStore, type CredentialStore } from "@earendil-works/pi-ai";
export type { CredentialStore };
export { InMemoryCredentialStore };

/** Hosts may inject their own store; P1 never creates auth.json. */
export function memoryCredentials(): CredentialStore {
  return new InMemoryCredentialStore();
}

export class Redactor {
  private readonly secrets = new Set<string>();
  add(secret: string): void {
    if (secret) this.secrets.add(secret);
  }
  text(value: string): string {
    for (const secret of [...this.secrets].sort((a, b) => b.length - a.length)) {
      value = value.split(secret).join("[REDACTED]");
    }
    return value;
  }
  clean<T>(value: T): T {
    if (typeof value === "string") return this.text(value) as T;
    if (Array.isArray(value)) return value.map((v) => this.clean(v)) as T;
    if (value && typeof value === "object") {
      return Object.fromEntries(Object.entries(value).map(([k, v]) => [this.text(k), this.clean(v)])) as T;
    }
    return value;
  }
}
import { ModelRuntime } from "@earendil-works/pi-coding-agent";
import type { Config, Credentials } from "../config/schema.ts";
import { type CredentialStore, Redactor } from "./credentials.ts";
import { DaemonError } from "../protocol/errors.ts";

export class Models {
  private constructor(
    public runtime: ModelRuntime,
    readonly credentials: CredentialStore,
    readonly redactor: Redactor,
  ) {}

  static async create(config: Config, credentials: CredentialStore, redactor: Redactor): Promise<Models> {
    const runtime = await Models.build(config, credentials);
    const result = new Models(runtime, credentials, redactor);
    for (const info of await credentials.list()) {
      const credential = await credentials.read(info.providerId);
      if (credential?.type === "api_key" && credential.key) redactor.add(credential.key);
    }
    return result;
  }

  private static async build(config: Config, credentials: CredentialStore): Promise<ModelRuntime> {
    const runtime = await ModelRuntime.create({ credentials, modelsPath: null, allowModelNetwork: false });
    for (const { id, ...provider } of config.providers) runtime.registerProvider(id, provider);
    if (runtime.getError()) throw new DaemonError("INVALID_PROVIDER", "Provider configuration is invalid");
    return runtime;
  }

  async apply(config: Config, keys: Credentials = {}): Promise<void> {
    for (const key of Object.values(keys)) if (key) this.redactor.add(key);
    const candidate = await Models.build(config, this.credentials);
    for (const [provider, key] of Object.entries(keys)) {
      if (key === null) await this.credentials.delete(provider);
      else await this.credentials.modify(provider, async () => ({ type: "api_key", key }));
    }
    this.runtime = candidate;
  }

  list() {
    return this.runtime.getModels().map(({ provider, id, name, reasoning, contextWindow, maxTokens }) => ({
      provider, id, name, reasoning, contextWindow, maxTokens,
    }));
  }
}
import assert from "node:assert/strict";
import { test } from "node:test";
import { fauxAssistantMessage } from "@earendil-works/pi-ai";
import { registerFauxProvider } from "@earendil-works/pi-ai/compat";
import { harness, providerConfig, result, until } from "./helpers.ts";

test("provider apply reports idle/running sessions to reopen; reopened sessions use new provider", async () => {
  let release!: (message: ReturnType<typeof fauxAssistantMessage>) => void;
  const h = await harness([fauxAssistantMessage("persist idle"), () => new Promise((resolve) => { release = resolve; })]);
  const next = registerFauxProvider({ models: [{ id: "new-model" }], tokensPerSecond: Infinity });
  try {
    const idle = result<{ sessionId: string }>(await h.request("session.open", { cwd: h.dir })).sessionId;
    await h.request("prompt", { sessionId: idle, text: "persist history" });
    await h.daemon.sessions.wait(idle);
    const running = result<{ sessionId: string }>(await h.request("session.open", { cwd: h.dir })).sessionId;
    await h.request("prompt", { sessionId: running, text: "old provider turn" });
    await until(() => !!release);
    const model = next.getModel();
    const applied = result<{ applied: boolean; reopenRequired: string[] }>(await h.request("config.apply", {
      config: { providers: [providerConfig(model)], defaultModel: { provider: model.provider, id: model.id } },
      credentials: { [model.provider]: "next-provider-key" },
    }));
    assert.equal(applied.applied, true);
    assert.deepEqual(applied.reopenRequired.sort(), [idle, running].sort());
    assert.equal(next.state.callCount, 0);
    release(fauxAssistantMessage("old provider finished"));
    await h.daemon.sessions.wait(running);
    assert.equal(h.events.filter((event) => event.sessionId === running).filter((event) => event.event === "text.delta").map((event) => event.text).join(""), "old provider finished");
    next.setResponses([fauxAssistantMessage("new provider finished"), fauxAssistantMessage("new provider finished")]);
    for (const id of [idle, running]) {
      await h.request("close", { sessionId: id });
      const reopened = result<{ model: { provider: string }; reopenRequired: boolean }>(
        await h.request("session.open", { sessionId: id }));
      assert.equal(reopened.model.provider, model.provider);
      assert.equal(reopened.reopenRequired, false);
      await h.request("prompt", { sessionId: id, text: "new provider turn" });
      await h.daemon.sessions.wait(id);
    }
    assert.equal(next.state.callCount, 2);
    assert.equal(h.faux.state.callCount, 2);
    assert.deepEqual(h.daemon.sessions.reopenRequired(), []);
  } finally { release?.(fauxAssistantMessage("cleanup")); await h.close(); next.unregister(); }
});

test("apply racing resource loading keeps model/runtime consistent and flags the opening session", async () => {
  let release!: () => void;
  const h = await harness([], { extensions: { enabled: true } }, [async () => {
    await new Promise<void>((resolve) => { release = resolve; });
  }]);
  try {
    const opening = h.request("session.open", { cwd: h.dir });
    await until(() => !!release);
    assert.ok((await h.request("config.apply", { config: { providers: [] } })).ok);
    release();
    const opened = result<{ sessionId: string; model: { provider: string }; reopenRequired: boolean }>(await opening);
    assert.equal(opened.model.provider, h.faux.getModel().provider);
    assert.equal(opened.reopenRequired, true);
    assert.deepEqual(h.daemon.sessions.reopenRequired(), [opened.sessionId]);
  } finally { release?.(); await h.close(); }
});

//! Pipe tasks use Tokio cancellation and per-write deadlines; owner kills/reaps
//! the child on every exit. Linux also uses PDEATHSIG, Windows a kill-on-close Job.
use super::{protocol::{Frame, Request}, super::config::Agentd};
use anyhow::{Context, Result};
use tokio::{io::{AsyncBufReadExt, AsyncWriteExt, BufReader}, process::{Child, Command}, sync::mpsc};
use std::{process::Stdio, time::Duration};

pub struct Process {
    child: Child,
    tasks: Vec<tokio::task::JoinHandle<()>>,
    pub writer: mpsc::Sender<Vec<u8>>,
    pub incoming: mpsc::Receiver<Result<Frame>>,
    pub pid: u32,
    shutdown_timeout: Duration,
    #[cfg(windows)]
    _job: super::windows_job::Job,
}
impl Process {
    pub fn spawn(config: &Agentd) -> Result<Self> {
        anyhow::ensure!(!config.entry.as_os_str().is_empty(), "AgentdEntryMissing: configure agentd.entry / POLARIS_AGENTD_ENTRY");
        let mut command = Command::new(&config.node);
        command.args(&config.node_args).arg(&config.entry).args(&config.args)
            .stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).kill_on_drop(true);
        crate::runtime::procs::no_window(command.as_std_mut());
        #[cfg(unix)]
        {
            use std::os::unix::process::CommandExt;
            command.as_std_mut().process_group(0);
        }
        #[cfg(target_os = "linux")]
        {
            let parent = std::process::id();
            unsafe {
                command.pre_exec(move || {
                    if libc::prctl(libc::PR_SET_PDEATHSIG, libc::SIGKILL) != 0 { return Err(std::io::Error::last_os_error()); }
                    if libc::getppid() != parent as i32 { return Err(std::io::Error::other("parent exited")); }
                    Ok(())
                });
            }
        }
        let mut child = command.spawn().context("AgentdSpawnFailed")?;
        let pid = child.id().context("AgentdPidMissing")?;
        #[cfg(windows)]
        let job = super::windows_job::Job::attach(pid)?;
        let stdout = child.stdout.take().context("AgentdStdoutMissing")?;
        let stderr = child.stderr.take().context("AgentdStderrMissing")?;
        let mut stdin = child.stdin.take().context("AgentdStdinMissing")?;
        let (tx, incoming) = mpsc::channel(config.channel_capacity);
        let limit = config.max_line_bytes;
        let output = tokio::spawn(async move {
            let mut reader = BufReader::new(stdout);
            loop {
                let frame = read_line(&mut reader, limit).await.and_then(|line| Frame::parse(&line));
                let failed = frame.is_err();
                if tx.send(frame).await.is_err() || failed { break; }
            }
        });
        let logging = tokio::spawn(async move {
            let mut reader = BufReader::new(stderr);
            while let Ok(line) = read_line(&mut reader, limit).await {
                eprintln!("{}", serde_json::json!({"component":"agentd.stderr", "pid":pid,
                    "line":String::from_utf8_lossy(&line)}));
            }
        });
        let (writer, mut rx) = mpsc::channel::<Vec<u8>>(config.channel_capacity);
        let timeout = Duration::from_millis(config.request_timeout_ms);
        let writing = tokio::spawn(async move {
            while let Some(line) = rx.recv().await {
                if !matches!(tokio::time::timeout(timeout, stdin.write_all(&line)).await, Ok(Ok(()))) { break; }
            }
        });
        Ok(Self { child, tasks: vec![output, logging, writing], writer, incoming, pid, shutdown_timeout: Duration::from_millis(config.shutdown_timeout_ms),
            #[cfg(windows)] _job: job })
    }
    pub fn write(&self, request: &Request, max: usize) -> Result<()> {
        let mut bytes = serde_json::to_vec(request)?;
        anyhow::ensure!(bytes.len() <= max, "AgentdLineTooLong: outgoing request");
        bytes.push(b'\n');
        self.writer.try_send(bytes).map_err(|_| anyhow::anyhow!("AgentdWriterBackpressure"))
    }
    pub fn exited(&mut self) -> Result<bool> { Ok(self.child.try_wait()?.is_some()) }
    pub async fn stop(&mut self) {
        for task in &self.tasks { task.abort(); }
        #[cfg(unix)]
        unsafe { libc::killpg(self.pid as i32, libc::SIGKILL); }
        let _ = self.child.start_kill();
        let _ = tokio::time::timeout(self.shutdown_timeout, self.child.wait()).await;
    }
}
impl Drop for Process {
    fn drop(&mut self) {
        for task in &self.tasks { task.abort(); }
        #[cfg(unix)]
        unsafe { libc::killpg(self.pid as i32, libc::SIGKILL); }
        let _ = self.child.start_kill();
    }
}
async fn read_line<R: tokio::io::AsyncBufRead + Unpin>(reader: &mut R, max: usize) -> Result<Vec<u8>> {
    let mut line = Vec::new();
    loop {
        let bytes = reader.fill_buf().await?;
        anyhow::ensure!(!bytes.is_empty(), "AgentdEof");
        let end = bytes.iter().position(|b| *b == b'\n');
        let count = end.map(|n| n + 1).unwrap_or(bytes.len());
        anyhow::ensure!(line.len() + count <= max + 1, "AgentdLineTooLong");
        line.extend_from_slice(&bytes[..count]);
        reader.consume(count);
        if end.is_some() { line.pop(); return Ok(line); }
    }
}
use super::{protocol::Command, supervisor, translate::Translator};
use super::super::{config::Agentd, stream::Mailbox, BackendStatus};
use std::{sync::{Arc, mpsc}, time::{Duration, Instant}};
use parking_lot::Mutex;
use serde_json::Value;
pub type Reply = mpsc::SyncSender<Result<Value, String>>;
pub enum Control {
    Request(Command, Reply),
    Register { session: String, req: String, translator: Translator, stream: Arc<Mailbox>, timeout: Duration, reservation: (Arc<Mutex<std::collections::HashSet<String>>>, String), reply: Reply },
    Cancel(String, Reply),
    Bind(String, String, Reply),
    Fail(String, String),
    Stop,
}
pub struct Client {
    pub config: Agentd,
    tx: tokio::sync::mpsc::Sender<Control>,
    pub status: Arc<Mutex<BackendStatus>>,
    pub active: Arc<Mutex<std::collections::HashMap<String, String>>>,
}
impl Client {
    pub fn new(config: Agentd) -> anyhow::Result<Arc<Self>> {
        let runtime = tokio::runtime::Builder::new_current_thread().enable_all().build()?;
        let (tx, rx) = tokio::sync::mpsc::channel(config.channel_capacity);
        let client = Arc::new(Self { config: config.clone(), tx,
            status: Arc::new(Mutex::new(BackendStatus::new("pi"))), active: Arc::new(Mutex::new(Default::default())) });
        let status = client.status.clone();
        let active = client.active.clone();
        std::thread::Builder::new().name("agentd-supervisor".into()).spawn(move || {
            runtime.block_on(supervisor::run(config, rx, status, active));
        })?;
        Ok(client)
    }
    pub fn send(&self, mut command: Control) -> anyhow::Result<()> {
        let deadline = Instant::now() + Duration::from_millis(self.config.request_timeout_ms);
        loop {
            match self.tx.try_send(command) {
                Ok(()) => return Ok(()),
                Err(tokio::sync::mpsc::error::TrySendError::Full(c)) => command = c,
                Err(_) => anyhow::bail!("AgentdSupervisorStopped"),
            }
            anyhow::ensure!(Instant::now() < deadline, "AgentdControlTimeout");
            std::thread::sleep(Duration::from_millis(self.config.control_poll_ms));
        }
    }
    pub fn call(&self, command: Command) -> anyhow::Result<Value> {
        let (tx, rx) = mpsc::sync_channel(1);
        self.send(Control::Request(command, tx))?;
        self.wait(rx)
    }
    pub fn wait(&self, rx: mpsc::Receiver<Result<Value, String>>) -> anyhow::Result<Value> {
        rx.recv_timeout(Duration::from_millis(self.config.request_timeout_ms))
            .map_err(|_| anyhow::anyhow!("AgentdRequestTimeout"))?.map_err(anyhow::Error::msg)
    }
    pub fn cancel(&self, req: &str) -> anyhow::Result<()> {
        let (tx, rx) = mpsc::sync_channel(1);
        self.send(Control::Cancel(req.into(), tx))?;
        self.wait(rx).map(|_| ())
    }
    pub fn stop(&self) { let _ = self.send(Control::Stop); }
}
impl Drop for Client { fn drop(&mut self) { let _ = self.tx.try_send(Control::Stop); } }

