//! UI delivery reuses the existing prompt assembly, artifact diff and persistence.
use super::*;
use crate::chat::ChatStreamEvent;
#[cfg(feature = "desktop")]
use tauri::Emitter;

pub(crate) fn run_chat(app: &AppHandle, req: &str, args: ChatSendArgs) -> Result<(), String> {
    let backend = selected().map_err(|e| e.to_string())?;
    let legacy = backend.status().backend == "claude-cli";
    let conv = args.conversation_id.clone();
    let permission = match args.permission_mode {
        PermissionMode::Manual => PermissionMode::Manual, PermissionMode::AutoAll => PermissionMode::AutoAll,
        PermissionMode::AutoCurrent => PermissionMode::AutoCurrent, PermissionMode::Deny => PermissionMode::Deny,
    };
    let mut input = TurnRequest {
        req_id: req.into(), session_id: conv.clone().unwrap_or_else(|| req.into()),
        conversation_id: conv.clone(), prompt: args.prompt.clone(), permission,
        model: None, cwd: claude_cli::pipeline::effective_cwd(None), attachments: vec![],
        account_id: None, timeout: None, legacy: None,
    };
    let mut snapshot = None;
    let mut notice = None;
    if legacy { input.legacy = Some((app.clone(), args)); }
    else {
        if args.use_sandbox { return Err(BackendError::UnsupportedInput("sandbox requires P3 tool routing").to_string()); }
        if args.provider_id.as_deref().is_some_and(|p| !p.is_empty() && p != "auto") {
            return Err(BackendError::UnsupportedInput("provider selection requires P4 mapping").to_string());
        }
        let prepared = claude_cli::pipeline::prepare(args);
        input.prompt = prepared.plan.full_text();
        input.cwd = claude_cli::pipeline::effective_cwd(prepared.project_work_dir.as_deref().map(std::path::Path::new));
        notice = prepared.image_notice;
        snapshot = Some((prepared.art_dir, prepared.art_before));
    }
    if crate::runtime::procs::CHILDREN.take_cancel(req) {
        emit(app, event(req, conv.as_deref(), "done", None));
        return Ok(());
    }
    let stream = backend.start(input).map_err(|e| e.to_string())?;
    let mut finalizer = None;
    let timeout = Duration::from_millis(config::Config::load().map_err(|e| e.to_string())?.agentd.turn_timeout_ms);
    loop {
        let ev = match stream.recv_timeout(timeout) {
            Ok(event) => event,
            Err(error) if legacy && matches!(error.downcast_ref(), Some(stream::StreamError::Timeout)) => continue,
            Err(error) => { let _ = backend.cancel(req); return Err(error.to_string()); }
        };
        if ev.kind == "done" {
            if let (Some(finalizer), Some((artifacts, before))) = (finalizer.take(), snapshot.take()) {
                let finalizer: claude_cli::pipeline::TurnStream = finalizer;
                finalizer.finish(&artifacts, &before);
            } else { emit(app, ev); }
            if conv.is_none() { let _ = backend.close(req); }
            crate::runtime::procs::CHILDREN.take_cancel(req);
            break;
        }
        if ev.kind == "meta" && !legacy {
            emit(app, ev);
            finalizer = Some(claude_cli::pipeline::TurnStream::new(app.clone(), req.into(), conv.clone(), notice.take()));
            continue;
        }
        if let Some(finalizer) = &mut finalizer { finalizer.record_backend_event(&ev); }
        emit(app, ev);
    }
    Ok(())
}
pub(crate) fn emit(app: &AppHandle, event: ChatStreamEvent) { let _ = app.emit("chat:stream", event); }
use super::protocol::{Event, TurnStatus};
use crate::chat::{backend::event, artifacts::{is_displayable_artifact, packaged_project_root}, ChatStreamEvent};
use std::{path::PathBuf, collections::HashMap, time::{Duration, Instant}};
use super::super::config::Agentd;

pub struct Translator {
    req: String, conv: Option<String>, cwd: PathBuf,
    tools: HashMap<String, String>, write_tools: Vec<String>,
    delta: String, last_flush: Instant, window: Duration, max_bytes: usize,
    error_seen: bool, done: bool,
}
impl Translator {
    pub fn new(req: String, conv: Option<String>, cwd: PathBuf, config: &Agentd) -> Self {
        Self { req, conv, cwd, tools: HashMap::new(), write_tools: config.write_tools.clone(),
            delta: String::new(), last_flush: Instant::now(), window: Duration::from_millis(config.delta_batch_ms),
            max_bytes: config.max_line_bytes, error_seen: false, done: false }
    }
    pub fn make(&self, kind: &str, text: Option<String>) -> ChatStreamEvent { event(&self.req, self.conv.as_deref(), kind, text) }
    pub fn flush(&mut self) -> Vec<ChatStreamEvent> {
        self.last_flush = Instant::now();
        if self.delta.is_empty() { vec![] } else {
            let text = std::mem::take(&mut self.delta);
            vec![self.make("delta", Some(text))]
        }
    }
    pub fn tick(&mut self) -> Vec<ChatStreamEvent> {
        if self.last_flush.elapsed() >= self.window { self.flush() } else { vec![] }
    }
    pub fn accept(&mut self, input: Event) -> Vec<ChatStreamEvent> {
        if self.done { return vec![]; }
        if let Event::Text { text } = input {
            let mut out = if self.delta.len() + text.len() > self.max_bytes { self.flush() } else { vec![] };
            self.delta.push_str(&text);
            out.extend(self.tick());
            return out;
        }
        let mut out = self.flush();
        match input {
            Event::ToolStarted { call_id, tool, args, .. } => {
                let path = args.get("path").and_then(|v| v.as_str());
                let summary = path.or_else(|| args.get("command").and_then(|v| v.as_str()))
                    .or_else(|| args.get("pattern").and_then(|v| v.as_str())).map(str::to_owned);
                let mut ev = self.make("tool", summary);
                ev.tool = Some(tool.clone());
                out.push(ev);
                if self.write_tools.contains(&tool) {
                    if let Some(path) = path {
                        self.tools.insert(call_id, self.cwd.join(path).to_string_lossy().replace('\\', "/"));
                    }
                }
            }
            Event::ToolCompleted { call_id, tool, is_error, .. } => {
                let path = self.tools.remove(&call_id);
                if is_error {
                    // A tool failure is visible, but the agent may recover and finish successfully.
                    out.push(self.make("error", Some(format!("ToolFailed: {tool} ({call_id})"))));
                } else if let Some(path) = path {
                    if is_displayable_artifact(&path) && packaged_project_root(std::path::Path::new(&path)).is_none() {
                        out.push(self.make("artifact", Some(path)));
                    }
                }
            }
            Event::Error { code, message } => { self.error_seen = true; out.push(self.make("error", Some(format!("{code}: {message}")))); }
            Event::Completed { status } => {
                if matches!(status, TurnStatus::Error | TurnStatus::Timeout) && !self.error_seen {
                    out.push(self.make("error", Some(format!("AgentdTurnFailed: {status:?}"))));
                }
                self.done = true;
                out.push(self.make("done", None));
            }
            Event::Started | Event::Reasoning { .. } | Event::Usage { .. } => {}
            Event::Text { .. } => {}
        }
        out
    }
}

//! Shared daemon adapter. Per-account fails closed until the shell can supply
